metadataQuery.sql:
begin read only;
set local search_path=pg_catalog;
select jsonb_build_object(
  'observedAt',clock_timestamp(),
  'stage',obj_description(to_regnamespace('business_auth'),'pg_namespace'),
  'history',(select coalesce(jsonb_agg(jsonb_build_object('name',name,'version',version,'sqlMd5',md5(array_to_string(statements,E'\n'))) order by version),'[]'::jsonb) from supabase_migrations.schema_migrations where name like 'qa_business_auth_%'),
  'stage4PrivateFunction',to_regprocedure('business_auth.triniti_business_signin_check(text,text,text,text,text)'),
  'musicSchemaPresent',to_regnamespace('music_library') is not null,
  'notificationEventJobsPresent',to_regclass('notification_delivery.event_jobs') is not null,
  'notificationEventClaimPresent',to_regprocedure('public.claim_notification_event_dispatch(uuid,text)') is not null,
  'activeBusinessAuthStatements',(select count(*) from pg_stat_activity where datname=current_database() and pid<>pg_backend_pid() and state='active' and (query ilike '%qa_business_auth_%' or query ilike '%business-auth:%' or query ilike '%BUSINESS_AUTH_STAGED%'))
) as postflight;
rollback;
